char *extract_word(const uint8_t **data, size_t *size)
{
        char *result = NULL;
        const uint8_t *ptr = NULL;

        if (*size < 2)
                return NULL;

        ptr = get_word(*data, *size);
        if (!ptr)
                return NULL;
        result = strdup((const char *)*data);
        *size -=(ptr - *data);
        *data = ptr;

        return result;
}
```

